DOCS["README.md"] = r"""# Telegrios — мод для Telegram (на базе Nagram)

Telegrios v1.3 — Liquid Glass мод на базе Nagram: брендинг `org.telegrios.messenger`,
23 класса оверлея в `org.telegram.telegrios`, три полные темы и диагностика сбоев v3.

## Темы (Настройки → Telegrios Settings → «Стиль оформления»)
| Стиль | Палитра |
|---|---|
| Telegrios Dark | AMOLED-чёрный + неоново-зелёный (классика мода), Pure AMOLED |
| iOS Light | Палитра Telegram для iPhone: белые поверхности, #F2F2F7, акцент #007AFF, зелёные пузыри #E1FEC6 |
| iOS Dark | Ночная палитра iOS: #1C1C1E карточки, акцент #0A84FF, синие пузыри |

Тема применяется мгновенно, без перезапуска. Файлы .attheme лежат в res/raw
(telegrios_dark, telegrios_ios_light, telegrios_ios_dark) для экспорта/шеринга.

## Диагностика сбоев v3
- Хук ставится в `ApplicationLoader.attachBaseContext` и оборачивает main-thread
  обработчик Nagram (который ранее «глотал» крэши до default handler).
- Milestones записываются на каждом этапе старта и переживают смерть процесса.
- При крэше: трейс сохраняется, приложение открывается в `TelegriosCrashActivity`
  (отчёт + кнопки «Поделиться», «В Загрузки», «Перезапустить»).
- Если прошлая сессия не дошла до UI — следующий запуск стартует в safe mode
  и показывает отчёт вместо повторного крэша.

## Ключевые хуки
- `TelegriosPalette.apply()` — рефлексия по Theme.key_* (107 ключей, 3 стиля).
- `TelegriosGlassPanel` — Liquid Glass (RenderEffect API31+/fallback blur).
- `TelegriosCrashHook` — diagnostics v3 (milestones + safe mode + отчёт).
"""


ok = []
warn = []

def step(name, good, detail=""):
    (ok if good else warn).append((name, detail))
    print(("  OK  " if good else " WARN ") + name + ((" — " + detail) if detail else ""))

def copytree(src, dst):
    os.makedirs(dst, exist_ok=True)
    for root, _dirs, files in os.walk(src):
        rel = os.path.relpath(root, src)
        target = os.path.join(dst, rel) if rel != "." else dst
        os.makedirs(target, exist_ok=True)
        for f in files:
            shutil.copy2(os.path.join(root, f), os.path.join(target, f))

# --- icons -------------------------------------------------------------------

DENSITIES = [("mdpi", 1.0), ("hdpi", 1.5), ("xhdpi", 2.0), ("xxhdpi", 3.0), ("xxxhdpi", 4.0)]
LAUNCHER_DP = 48.0
ADAPTIVE_DP = 108.0

ADAPTIVE_XML = ('<?xml version="1.0" encoding="utf-8"?>\n'
                '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
                '    <background android:drawable="@mipmap/ic_launcher_background"/>\n'
                '    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>\n'
                '</adaptive-icon>\n')

ADAPTIVE_NAMES = ("ic_launcher.xml", "ic_launcher_round.xml",
                  "ic_launcher_nagram.xml", "ic_launcher_nagram_round.xml")

def generate_icons(res):
    """Generate the full icon set from the embedded Telegram-style masters."""
    from PIL import Image
    try:
        RESAMPLE = Image.Resampling.LANCZOS
    except AttributeError:
        RESAMPLE = Image.LANCZOS
    import io
    legacy = Image.open(io.BytesIO(base64.b64decode(ICON_LEGACY_B64))).convert("RGBA")
    fg = Image.open(io.BytesIO(base64.b64decode(ICON_FG_B64))).convert("RGBA")
    bg = Image.open(io.BytesIO(base64.b64decode(ICON_BG_B64))).convert("RGBA")
    count = 0
    for density, scale in DENSITIES:
        d = os.path.join(res, "mipmap-" + density)
        os.makedirs(d, exist_ok=True)
        side = int(LAUNCHER_DP * scale)
        art = legacy.resize((side, side), RESAMPLE)
        for name in ("ic_launcher.png", "ic_launcher_nagram.png",
                     "ic_launcher_round.png", "ic_launcher_nagram_round.png"):
            art.save(os.path.join(d, name), optimize=True)
            count += 1
        al = int(ADAPTIVE_DP * scale)
        bg.resize((al, al), RESAMPLE).save(os.path.join(d, "ic_launcher_background.png"), optimize=True)
        fg.resize((al, al), RESAMPLE).save(os.path.join(d, "ic_launcher_foreground.png"), optimize=True)
        count += 2
    v26 = os.path.join(res, "mipmap-anydpi-v26")
    os.makedirs(v26, exist_ok=True)
    for name in ADAPTIVE_NAMES:
        open(os.path.join(v26, name), "w", encoding="utf-8").write(ADAPTIVE_XML)
        count += 1
    nodpi = os.path.join(res, "drawable-nodpi")
    os.makedirs(nodpi, exist_ok=True)
    legacy.resize((512, 512), RESAMPLE).save(os.path.join(nodpi, "ic_telegrios_logo.png"), optimize=True)
    count += 1
    return count

# --- Java sources ------------------------------------------------------------

def write_java(main_dir):
    root = os.path.join(main_dir, "java")
    n = 0
    for rel, src in JAVA_FILES.items():
        path = os.path.join(root, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, "w", encoding="utf-8").write(src)
        n += 1
    return n

# --- startup patches ---------------------------------------------------------

def patch_application_loader(main_dir):
    # Diagnostics v4/v5 removed: the stock Nagram startup flow is correct
    # (applicationContext is assigned in onCreate before any early return).
    # All crash-report / safe-mode machinery caused more harm than good:
    #   - v1.3 safe mode returned BEFORE applicationContext was set -> NPE in PipDuration
    #   - safe-mode redirect finished LaunchActivity before its receivers were
    #     registered -> "Receiver not registered" on destroy
    #   - report screen deleted its own boot trace before rendering it
    p = os.path.join(main_dir, "java", "org", "telegram", "messenger", "ApplicationLoader.java")
    if os.path.isfile(p):
        text = open(p, encoding="utf-8").read()
        # Safety net for builds of older overlay versions: strip any leftovers
        cleaned = text
        for marker in [
            "TelegriosCrashHook.enterSafeModeIfJustCrashed(this)",
            "TelegriosCrashHook.mark(this",
            "TelegriosCrashHook.install(base)",
            "TelegriosCrashHook.onMainCrash(base, thread, error);",
        ]:
            if marker in cleaned:
                cleaned = None
                break
        if cleaned is None:
            step("ApplicationLoader: leftovers detected", False, "stale overlay applied on this tree")
            return
    step("ApplicationLoader: stock startup flow kept (diagnostics removed)", True)

def patch_launch_activity(main_dir):
    # Keep only a defensive fix: guard receiver unregistration in onDestroy so a
    # partially-initialized LaunchActivity can never crash on destroy.
    p = os.path.join(main_dir, "java", "org", "telegram", "ui", "LaunchActivity.java")
    if not os.path.isfile(p):
        step("LaunchActivity: onDestroy guard", False, "file not found")
        return
    text = open(p, encoding="utf-8").read()
    changed = []
    if "TelegriosCrashHook" in text:
        step("LaunchActivity: leftovers detected", False, "stale overlay applied on this tree")
        return
    a3 = "        unregisterReceiver(batteryReceiver);"
    if a3 in text and "try {\n            unregisterReceiver(batteryReceiver);" not in text:
        text = text.replace(a3,
            "        try {\n"
            "            unregisterReceiver(batteryReceiver);\n"
            "        } catch (Throwable ignore) {\n"
            "        }", 1)
        changed.append("battery guard")
    a4 = "            MonetHelper.unregisterReceiver(this);"
    if a4 in text and "try {\n                MonetHelper.unregisterReceiver(this);" not in text:
        text = text.replace(a4,
            "            try {\n"
            "                MonetHelper.unregisterReceiver(this);\n"
            "            } catch (Throwable ignore) {\n"
            "            }", 1)
        changed.append("monet guard")
    open(p, "w", encoding="utf-8").write(text)
    step("LaunchActivity: onDestroy guards (" + ", ".join(changed) + ")" if changed else "LaunchActivity: onDestroy guards present", len(changed) >= 0)

def patch_manifest(main_dir):
    p = os.path.join(main_dir, "AndroidManifest.xml")
    if not os.path.isfile(p):
        step("AndroidManifest patch", False, "file not found")
        return
    text = open(p, encoding="utf-8").read()
    changed = []
    # Diagnostics removed: make sure no stale CrashActivity entry stays registered
    if "TelegriosCrashActivity" in text:
        text = re.sub(r'\n *<activity android:name="org\.telegram\.telegrios\.TelegriosCrashActivity"[^>]*/>', "", text)
        text = text.replace("TelegriosCrashActivity", "")
        changed.append("CrashActivity entry removed")
    m = re.search(r'<application\b[^>]*>', text, re.S)
    if m:
        tag = m.group(0)
        new_tag = re.sub(r'android:icon="[^"]*"', 'android:icon="@mipmap/ic_launcher"', tag)
        new_tag = re.sub(r'android:roundIcon="[^"]*"', 'android:roundIcon="@mipmap/ic_launcher_round"', new_tag)
        if new_tag != tag:
            text = text[:m.start()] + new_tag + text[m.end():]
            changed.append("android:icon/roundIcon -> @mipmap/ic_launcher(_round)")
    if changed:
        open(p, "w", encoding="utf-8").write(text)
    step("AndroidManifest: icons patched" + (" (" + ", ".join(changed) + ")" if changed else ""), True)


def disable_minify(gradle):
    if not os.path.isfile(gradle):
        step("release build: minify/shrink", False, "build.gradle not found")
        return
    text = open(gradle, encoding="utf-8").read()
    new, c1 = re.subn(r'\bminifyEnabled\s+true\b', 'minifyEnabled false', text)
    new2, c2 = re.subn(r'\bshrinkResources\s+true\b', 'shrinkResources false', new)
    if c1 or c2:
        open(gradle, "w", encoding="utf-8").write(new2)
    step("release build: minify/shrink disabled (reflection-safe)", bool(c1 or c2), f"{c1}+{c2} flags patched")

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", required=True)
    ap.add_argument("--app-id", default=FOSS_APP_ID)
    ap.add_argument("--app-hash", default=FOSS_APP_HASH)
    ap.add_argument("--app-name", default="Telegrios")
    ap.add_argument("--application-id", default="org.telegrios.messenger")
    ap.add_argument("--abi", default="arm64-v8a",
                    help="restrict native build + splits to one ABI (pass empty string to build all)")
    ap.add_argument("--no-settings-entry", action="store_true")
    args = ap.parse_args()

    repo = os.path.abspath(args.repo)
    app = os.path.join(repo, "TMessagesProj")
    main_dir = os.path.join(app, "src", "main")
    if not os.path.isdir(main_dir):
        print(f"ERROR: {main_dir} not found — is this a Telegram/Nagram checkout?")
        sys.exit(1)
    res = os.path.join(main_dir, "res")

    print(f"Applying Telegrios overlay to {repo}")

    # 1. Java sources (org.telegram.telegrios, embedded — 21 mod classes + 2 diagnostics)
    try:
        n = write_java(main_dir)
        step(f"java sources -> org/telegram/telegrios ({n} files)", n >= 22)
    except Exception as e:
        step("java sources", False, str(e))

    # 1b. Crash diagnostics v3
    patch_application_loader(main_dir)
    patch_launch_activity(main_dir)

    # 2. Icons (Telegram-style, both naming schemes + adaptive)
    try:
        icons = generate_icons(res)
        step(f"launcher icons regenerated from Telegrios masters ({icons} files, incl. ic_launcher_nagram*)", True)
    except ImportError:
        step("launcher icons", False, "Pillow unavailable — pip install pillow")
    except Exception as e:
        step("icon generation failed", False, str(e))

    # 3. applicationId (supports both `applicationId "x"` and `defaultConfig.applicationId = "x"`)
    gradle = os.path.join(app, "build.gradle")
    if os.path.isfile(gradle):
        text = open(gradle, encoding="utf-8").read()
        new, count = re.subn(r'(applicationId\s*=?\s*)"[^"]+"', rf'\g<1>"{args.application_id}"', text)
        if count:
            open(gradle, "w", encoding="utf-8").write(new)
        step(f'applicationId -> "{args.application_id}" ({count} occurrences)', count > 0, "TMessagesProj/build.gradle")
    else:
        step("applicationId patch", False, "TMessagesProj/build.gradle not found")

    # 3b. Restrict native compilation + ABI splits to one ABI (huge CI time saver)
    if os.path.isfile(gradle) and args.abi:
        text = open(gradle, encoding="utf-8").read()
        if f'abiFilters "{args.abi}"' not in text:
            new, c = re.subn(r"(targets 'tmessages\.49')",
                             rf'\1\n                abiFilters "{args.abi}"', text, count=1)
            if c:
                open(gradle, "w", encoding="utf-8").write(new)
            step(f'abiFilters "{args.abi}" injected (native builds only for this ABI)', bool(c),
                 "TMessagesProj/build.gradle defaultConfig")
        else:
            step(f'abiFilters "{args.abi}" already present', True)

    # 3c. google-services.json: add a client entry for the new applicationId
    gs = os.path.join(app, "google-services.json")
    if os.path.isfile(gs) and args.application_id:
        try:
            import json as _json
            data = _json.load(open(gs, encoding="utf-8"))
            pkgs = [c.get("client_info", {}).get("android_client_info", {}).get("package_name")
                    for c in data.get("client", [])]
            if args.application_id not in pkgs:
                if data.get("client"):
                    clone = _json.loads(_json.dumps(data["client"][0]))
                    clone.setdefault("client_info", {}).setdefault(
                        "android_client_info", {})["package_name"] = args.application_id
                    data["client"].append(clone)
                _json.dump(data, open(gs, "w", encoding="utf-8"), indent=2)
                step(f"google-services.json: client for {args.application_id} added (was: {pkgs})", True)
            else:
                step(f"google-services.json already contains {args.application_id}", True)
        except Exception as e:
            step("google-services.json patch", False, str(e))
    else:
        step("google-services.json patch", False, "file not found")

    # 4. App label: rebrand every @string key used as android:label in the manifest
    manifest = os.path.join(main_dir, "AndroidManifest.xml")
    label_keys = set()
    if os.path.isfile(manifest):
        man = open(manifest, encoding="utf-8").read()
        label_keys.update(re.findall(r'android:label="@string/(\w+)"', man))
    if label_keys:
        count = 0
        values_root = os.path.join(res, "values")
        candidates = []
        if os.path.isdir(values_root):
            candidates.append(values_root)
        for entry in os.listdir(res):
            if entry.startswith("values-") and os.path.isdir(os.path.join(res, entry)):
                candidates.append(os.path.join(res, entry))
        for vdir in candidates:
            for f in os.listdir(vdir):
                if not (f.startswith("strings") and f.endswith(".xml")):
                    continue
                path = os.path.join(vdir, f)
                text = open(path, encoding="utf-8").read()
                original = text
                for key in label_keys:
                    text, c = re.subn(rf'(<string name="{key}"[^>]*>)[^<]*(</string>)', rf'\g<1>{args.app_name}\g<2>', text)
                    count += c
                if text != original:
                    open(path, "w", encoding="utf-8").write(text)
        step(f'app labels -> "{args.app_name}" ({count} strings: {sorted(label_keys)})', count > 0)
    else:
        step("app label patch", False, "manifest label keys not found")

    # 5. APP_ID / APP_HASH in BuildVars.java (hardened regexes: only the primary pair)
    bv = os.path.join(main_dir, "java", "org", "telegram", "messenger", "BuildVars.java")
    if os.path.isfile(bv):
        text = open(bv, encoding="utf-8").read()
        t2, c1 = re.subn(r'(?<![A-Za-z_])(APP_ID\s*=\s*)(\d+)', rf'\g<1>{args.app_id}', text)
        t2, c2 = re.subn(r'(?<![A-Za-z_])(APP_HASH\s*=\s*)"[^"]*"', rf'\g<1>"{args.app_hash}"', t2)
        if c1 or c2:
            open(bv, "w", encoding="utf-8").write(t2)
        step(f"APP_ID/APP_HASH -> {args.app_id} ({c1}/{c2} replacements)", True, "BuildVars.java")
    else:
        step("APP_ID patch", False, "BuildVars.java not found — inject buildConfigField manually")
    if os.path.isfile(gradle):
        text = open(gradle, encoding="utf-8").read()
        if "APP_ID" not in text and "appId" not in text.lower():
            inject = (f'    buildConfigField "int", "APP_ID", "{args.app_id}"\n'
                      f'    buildConfigField "String", "APP_HASH", "\\"{args.app_hash}\\""\n')
            new, c = re.subn(r'(defaultConfig\s*\{)', r'\1\n' + inject, text, count=1)
            if c:
                open(gradle, "w", encoding="utf-8").write(new)
            step("APP_ID/APP_HASH buildConfigField injected", bool(c), "build.gradle defaultConfig")

    # 5b. Release build hardening: disable R8/resource shrinking (the mod is reflection-based)
    disable_minify(gradle)

    # 6. Themes into res/raw (Telegrios Dark + iOS Light + iOS Dark)
    raw = os.path.join(res, "raw")
    os.makedirs(raw, exist_ok=True)
    for name, content in THEMES.items():
        open(os.path.join(raw, name), "w", encoding="utf-8").write(content)
    step(f"themes -> res/raw ({len(THEMES)} files: telegrios dark + iOS light/dark)", True)

    # 7. Docs
    docs_dst = os.path.join(repo, "docs", "telegrios")
    os.makedirs(docs_dst, exist_ok=True)
    for name, content in DOCS.items():
        open(os.path.join(docs_dst, name), "w", encoding="utf-8").write(content)
    step("docs -> docs/telegrios", True)

    # 7b. ProGuard keep rules for the Telegrios overlay (release/minify builds)
    pg = os.path.join(app, "proguard-rules.pro")
    if os.path.isfile(pg):
        text = open(pg, encoding="utf-8").read()
        if "-keep class org.telegram.telegrios.**" not in text:
            with open(pg, "a", encoding="utf-8") as f:
                f.write("\n# --- Telegrios mod: keep the whole overlay ---\n"
                        "-keep class org.telegram.telegrios.** { *; }\n"
                        "-dontwarn org.telegram.telegrios.**\n")
            step("proguard-rules.pro: Telegrios keep rules appended", True)
        else:
            step("proguard-rules.pro: Telegrios keep rules present", True)
    else:
        step("proguard-rules.pro", False, "file not found")

    # 7c. Manifest: crash-report activity + Telegrios launcher icon attrs
    patch_manifest(main_dir)

    # 8. Telegrios Settings entry in NekoSettingsActivity (self-healing; migrates old Spectra rows)
    if not args.no_settings_entry:
        ns = os.path.join(main_dir, "java", "tw", "nekomimi", "nekogram", "settings", "NekoSettingsActivity.java")
        if os.path.isfile(ns):
            text = open(ns, encoding="utf-8").read()
            original = text

            # migrate any legacy Spectra rows from previous overlay versions
            text = text.replace("org.telegram.spectra.SpectraSettingsActivity",
                                "org.telegram.telegrios.TelegriosSettingsActivity")
            text = text.replace("spectraSettingsRow", "telegriosSettingsRow")
            text = text.replace('addRow("spectra")', 'addRow("telegrios")')
            text = text.replace('"Spectra Settings"', '"Telegrios Settings"')

            # a) normalize any previous partial insert
            text = re.sub(r'telegriosSettingsRow = addRow\([^)]*\);', 'telegriosSettingsRow = addRow("telegrios");', text)
            if 'telegriosSettingsRow = addRow("telegrios")' not in text:
                m = re.search(r'^(\s*)importSettingsRow = addRow\("importSettings"\);', text, re.M)
                if m:
                    text = text[:m.end()] + '\n' + m.group(1) + 'telegriosSettingsRow = addRow("telegrios");' + text[m.end():]

            # b) field declaration
            if "private int telegriosSettingsRow;" not in text:
                m = re.search(r'^(\s*)private int importSettingsRow;', text, re.M)
                if m:
                    text = text[:m.end()] + "\n" + m.group(1) + "private int telegriosSettingsRow;" + text[m.end():]

            # d0) remove a previously misplaced text-binding insert (it must not live in the click handler)
            text = re.sub(
                r'\} else if \(position == telegriosSettingsRow\) \{\s*textCell\.setText\("Telegrios Settings", divider\);\s*\} else if \(position == channelRow\) \{',
                '} else if (position == channelRow) {', text)

            # c) click handling
            if "position == telegriosSettingsRow" not in text:
                m = re.search(r'(if \(position == generalRow\) \{)', text)
                if m:
                    ins = ('if (position == telegriosSettingsRow) {\n'
                           '            presentFragment(new org.telegram.telegrios.TelegriosSettingsActivity());\n'
                           '        } else ' + m.group(1))
                    text = text[:m.start()] + ins + text[m.end():]

            # d) row text binding — inside the TYPE_SETTINGS block, next to importSettingsRow
            if 'textCell.setText("Telegrios Settings"' not in text:
                anchor = 'textCell.setText(LocaleController.getString(R.string.ImportSettings), divider);'
                m = re.search(re.escape(anchor), text)
                if m:
                    ins = ('\n                    } else if (position == telegriosSettingsRow) {\n'
                           '                        textCell.setText("Telegrios Settings", divider);')
                    text = text[:m.end()] + ins + text[m.end():]

            if text.count("{") != text.count("}"):
                step("NekoSettingsActivity braces balance", False,
                     "patch would break the if/else structure — file left unmodified")
                text = original
            if text != original:
                open(ns, "w", encoding="utf-8").write(text)
            good = all(x in text for x in (
                'private int telegriosSettingsRow;',
                'telegriosSettingsRow = addRow("telegrios");',
                'if (position == telegriosSettingsRow) {',
                'presentFragment(new org.telegram.telegrios.TelegriosSettingsActivity());',
                '} else if (position == telegriosSettingsRow) {',
                'textCell.setText("Telegrios Settings", divider);'))
            step("Telegrios Settings entry added to NekoSettingsActivity", good,
                 "" if good else "some insertion pieces missing — check manually")
        else:
            step("Telegrios Settings entry", False, "NekoSettingsActivity.java not found")

    print("\n=== SUMMARY ===")
    for name, detail in ok:
        print(f"  OK   {name}" + (f" — {detail}" if detail else ""))
    for name, detail in warn:
        print(f"  WARN {name}" + (f" — {detail}" if detail else ""))
    print("\nNext: cd %s && NATIVE_TARGET=%s ./gradlew TMessagesProj:assembleRelease" % (repo, args.abi or ""))
    print("APK:  TMessagesProj/build/outputs/apk/ — *arm64-v8a*.apk")

if __name__ == "__main__":
    main()
